package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type AmtRec struct {
	ArAcct string
	ArAmt  decimal.Decimal
}

var WsEofFlag string = "N"
var WsBigTotal decimal.Decimal = decimal.Zero
var WsWrapTotal decimal.Decimal = decimal.Zero
var WsSafeTotal decimal.Decimal = decimal.Zero
var WsOverflows int64 = 0
var WsCount int64 = 0
var WsHalf decimal.Decimal = decimal.Zero
var WsAmtEd string
var WsWrapEd string
var WsSafeEd string
var WsHalfEd string

var ArAcct string
var ArAmt decimal.Decimal

var amtFileLines []string
var amtFileIdx int

func isInputDone() bool { return WsEofFlag == "Y" }

func storeWrap(value decimal.Decimal, intDigits int32, scale int32) decimal.Decimal {
	v := value.Truncate(scale)
	modInt := int64(1)
	for i := int32(0); i < intDigits; i++ {
		modInt *= 10
	}
	// work in scaled integer units to do modulo exactly
	scaled := v.Shift(scale)
	// Truncate toward zero already done; get integer part
	n := scaled.Truncate(0).IntPart()
	pow10scale := int64(1)
	for i := int32(0); i < scale; i++ {
		pow10scale *= 10
	}
	modScaled := modInt * pow10scale
	r := n % modScaled
	return decimal.New(r, -scale)
}

func formatZZZZ9_99(v decimal.Decimal) string {
	// PIC ZZ,ZZ9.99 : 5 int digits, 2 dec
	w := storeWrap(v, 5, 2)
	// get integer and decimal parts (non-negative expected)
	neg := w.IsNegative()
	if neg {
		w = w.Neg()
	}
	w = w.Truncate(2)
	ip := w.IntPart()
	frac := w.Shift(2).Sub(decimal.New(ip, 0).Shift(2)).IntPart()
	if frac < 0 {
		frac = -frac
	}
	if ip < 0 {
		ip = -ip
	}
	// wrap ip already <100000
	s5 := fmt.Sprintf("%05d", ip)
	d0 := s5[0]
	d1 := s5[1]
	d2 := s5[2]
	d3 := s5[3]
	d4 := s5[4]
	chars := []byte{d0, d1, ',', d2, d3, d4, '.', byte('0' + frac/10), byte('0' + frac%10)}
	// Z suppression for first 4 int digits: indices 0,1,3,4
	suppIdx := []int{0, 1, 3, 4}
	for _, idx := range suppIdx {
		if chars[idx] == '0' {
			chars[idx] = ' '
		} else {
			break
		}
	}
	// comma becomes space if all int digits to its left are spaces
	leftAllSpace := true
	for _, idx := range []int{0, 1} {
		if chars[idx] != ' ' {
			leftAllSpace = false
			break
		}
	}
	if leftAllSpace {
		chars[2] = ' '
	}
	s := string(chars)
	if neg {
		_ = neg
	}
	return s
}

func formatZZZZ9_9(v decimal.Decimal) string {
	// PIC ZZ,ZZ9.9 : 5 int digits, 1 dec
	w := storeWrap(v, 5, 1)
	if w.IsNegative() {
		w = w.Neg()
	}
	w = w.Truncate(1)
	ip := w.IntPart()
	frac := w.Shift(1).Sub(decimal.New(ip, 0).Shift(1)).IntPart()
	if frac < 0 {
		frac = -frac
	}
	if ip < 0 {
		ip = -ip
	}
	s5 := fmt.Sprintf("%05d", ip)
	chars := []byte{s5[0], s5[1], ',', s5[2], s5[3], s5[4], '.', byte('0' + frac)}
	suppIdx := []int{0, 1, 3, 4}
	for _, idx := range suppIdx {
		if chars[idx] == '0' {
			chars[idx] = ' '
		} else {
			break
		}
	}
	leftAllSpace := true
	for _, idx := range []int{0, 1} {
		if chars[idx] != ' ' {
			leftAllSpace = false
			break
		}
	}
	if leftAllSpace {
		chars[2] = ' '
	}
	return string(chars)
}

func parseAmtField(s string) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.Zero
	}
	// digits only
	var n int64
	for _, c := range s {
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		}
	}
	return decimal.New(n, -2)
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func main() {
	// OPEN INPUT AMT-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			amtFileLines = []string{}
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		sc := bufio.NewScanner(f)
		// allow long lines
		sc.Buffer(make([]byte, 1024*1024), 1024*1024)
		for sc.Scan() {
			line := sc.Text()
			// strip trailing \r if any
			line = strings.TrimSuffix(line, "\r")
			amtFileLines = append(amtFileLines, line)
		}
		f.Close()
	}
	amtFileIdx = 0
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	// CLOSE AMT-FILE (nothing)
	SummaryPara()
}

func ReadPara() {
	if amtFileIdx >= len(amtFileLines) {
		WsEofFlag = "Y"
		return
	}
	line := amtFileLines[amtFileIdx]
	amtFileIdx++
	// pad to 11 with spaces
	if len(line) < 11 {
		line = line + strings.Repeat(" ", 11-len(line))
	}
	if len(line) > 11 {
		line = line[:11]
	}
	ArAcct = line[0:4]
	ArAmt = parseAmtField(line[4:11])
}

func ProcessPara() {
	// ADD AR-AMT TO WS-BIG-TOTAL
	WsBigTotal = storeWrap(WsBigTotal.Add(ArAmt), 7, 2)
	// MOVE WS-BIG-TOTAL TO WS-WRAP-TOTAL
	WsWrapTotal = storeWrap(WsBigTotal, 5, 2)
	// ADD AR-AMT TO WS-SAFE-TOTAL ON SIZE ERROR PERFORM OVERFLOW-PARA END-ADD
	sum := WsSafeTotal.Add(ArAmt).Truncate(2)
	limit := decimal.New(100000, 0)
	nlimit := decimal.New(-100000, 0)
	if sum.GreaterThanOrEqual(limit) || sum.LessThanOrEqual(nlimit) {
		OverflowPara()
	} else {
		WsSafeTotal = storeWrap(sum, 5, 2)
	}
	// ADD 1 TO WS-COUNT
	WsCount = (WsCount + 1) % 100
	// COMPUTE WS-HALF = AR-AMT / 2 (truncated)
	q := ArAmt.Div(decimal.New(2, 0))
	q = q.Truncate(1)
	WsHalf = storeWrap(q, 5, 1)
	// MOVEs to edited
	WsAmtEd = formatZZZZ9_99(ArAmt)
	WsWrapEd = formatZZZZ9_99(WsWrapTotal)
	WsSafeEd = formatZZZZ9_99(WsSafeTotal)
	WsHalfEd = formatZZZZ9_9(WsHalf)
	// DISPLAY
	acct := padRight(ArAcct, 4)
	fmt.Printf("%s %s %s %s %s\n", acct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)
	ReadPara()
}

func SummaryPara() {
	fmt.Printf("RECORDS: %02d\n", WsCount%100)
	fmt.Printf("OVERFLOWS: %02d\n", WsOverflows%100)
}

func OverflowPara() {
	WsOverflows = (WsOverflows + 1) % 100
}
